// Initialize event cascade processing
const triggerData = $input.first().json;
const {
  campaignId,
  initialEvent,
  cascadeDepth = 3,
  propagationSpeed = 'normal', // slow, normal, fast
  affectedSystems = ['all'], // all, npcs, factions, locations, economy
  playerInvolvement = false
} = triggerData;

// Validate required fields
if (!campaignId || !initialEvent) {
  throw new Error('Missing required fields: campaignId, initialEvent');
}

// Prepare cascade configuration
const cascadeConfig = {
  cascadeId: `cascade_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
  campaignId,
  initialEvent: {
    ...initialEvent,
    id: initialEvent.id || `event_${Date.now()}`,
    timestamp: initialEvent.timestamp || new Date().toISOString(),
    source: initialEvent.source || 'external',
    magnitude: initialEvent.magnitude || 'normal', // minor, normal, major, catastrophic
    type: initialEvent.type || 'unknown'
  },
  cascadeDepth,
  propagationSpeed,
  affectedSystems,
  playerInvolvement,
  startTime: new Date().toISOString(),
  currentDepth: 0,
  propagationHistory: [],
  cascadeBranches: [],
  systemState: {
    active: true,
    paused: false,
    completed: false,
    errors: []
  }
};

return [{ json: cascadeConfig }];

// Analyze initial event and determine propagation patterns
const cascadeConfig = $input.first().json;
const worldContext = $input.last().json;

const { worldState, cascadeHistory, relationships } = worldContext.results[0] || {};
const { initialEvent } = cascadeConfig;

// Analyze event characteristics
const eventAnalysis = {
  event_type: initialEvent.type,
  magnitude: initialEvent.magnitude,
  propagation_vectors: determinePropagationVectors(initialEvent, worldState),
  affected_domains: determineAffectedDomains(initialEvent, worldState),
  cascade_potential: calculateCascadePotential(initialEvent, worldState),
  propagation_delay: calculatePropagationDelay(cascadeConfig.propagationSpeed, initialEvent.magnitude),
  resonance_factors: identifyResonanceFactors(initialEvent, worldState)
};

function determinePropagationVectors(event, worldState) {
  const vectors = [];

  // Location-based propagation
  if (event.location_id && worldState.locations) {
    const location = worldState.locations.find(loc => loc.id === event.location_id);
    if (location) {
      vectors.push({
        type: 'location',
        target: location.id,
        strength: 0.8,
        connected_locations: location.connections || []
      });
    }
  }

  // NPC-based propagation
  if (event.npc_id && worldState.npcs) {
    const npc = worldState.npcs.find(n => n.id === event.npc_id);
    if (npc) {
      vectors.push({
        type: 'npc',
        target: npc.id,
        strength: 0.7,
        relationships: Object.keys(npc.relationships || {}),
        location: npc.location
      });
    }
  }

  // Faction-based propagation
  if (event.faction_id && worldState.factions) {
    const faction = worldState.factions.find(f => f.id === event.faction_id);
    if (faction) {
      vectors.push({
        type: 'faction',
        target: faction.id,
        strength: 0.9,
        relationships: Object.keys(faction.relationships || {}),
        territories: faction.territories || []
      });
    }
  }

  // Economic propagation
  if (['economic_change', 'trade', 'resource'].includes(event.type)) {
    vectors.push({
      type: 'economic',
      strength: 0.6,
      market_regions: ['local', 'regional', 'global'],
      trade_routes: worldState.trade_routes || []
    });
  }

  // Environmental propagation
  if (['environmental', 'weather', 'natural_disaster'].includes(event.type)) {
    vectors.push({
      type: 'environmental',
      strength: 0.75,
      affected_biomes: ['all'],
      spread_pattern: 'radial'
    });
  }

  return vectors;
}

function determineAffectedDomains(event, worldState) {
  const domains = [];

  // Direct domain impacts
  const domainMappings = {
    'combat': ['locations', 'npcs', 'factions'],
    'social': ['npcs', 'factions', 'locations'],
    'economic': ['economy', 'factions', 'locations'],
    'environmental': ['locations', 'npcs', 'economy'],
    'political': ['factions', 'npcs', 'locations'],
    'magical': ['locations', 'npcs', 'economy', 'factions'],
    'divine': ['npcs', 'factions', 'locations', 'economy']
  };

  if (domainMappings[event.type]) {
    domains.push(...domainMappings[event.type]);
  }

  // Magnitude-based domain expansion
  if (event.magnitude === 'major' || event.magnitude === 'catastrophic') {
    domains.push('all');
  }

  return [...new Set(domains)];
}

function calculateCascadePotential(event, worldState) {
  let potential = 0.5; // Base potential

  // Magnitude factor
  const magnitudeFactors = {
    'minor': 0.2,
    'normal': 0.5,
    'major': 0.8,
    'catastrophic': 1.0
  };
  potential += magnitudeFactors[event.magnitude] || 0.5;

  // World state complexity factor
  const complexity = (worldState.locations?.length || 0) + 
                    (worldState.npcs?.length || 0) + 
                    (worldState.factions?.length || 0);
  potential += Math.min(complexity / 50, 0.3);

  // Relationship density factor
  const relationshipDensity = Object.keys(relationships || {}).length;
  potential += Math.min(relationshipDensity / 20, 0.2);

  return Math.min(potential, 1.0);
}

function calculatePropagationDelay(speed, magnitude) {
  const baseDelays = {
    'slow': { 'minor': 24, 'normal': 12, 'major': 6, 'catastrophic': 2 },
    'normal': { 'minor': 12, 'normal': 6, 'major': 3, 'catastrophic': 1 },
    'fast': { 'minor': 6, 'normal': 3, 'major': 1.5, 'catastrophic': 0.5 }
  };

  return (baseDelays[speed] || baseDelays['normal'])[magnitude] || 6;
}

function identifyResonanceFactors(event, worldState) {
  const factors = [];

  // Pre-existing tensions
  if (worldState.factions) {
    const tenseFactions = worldState.factions.filter(f => 
      (f.relationships && Object.values(f.relationships).some(rel => rel < -30))
    );
    if (tenseFactions.length > 0) {
      factors.push({
        type: 'faction_tension',
        description: 'Pre-existing faction tensions may amplify effects',
        multiplier: 1.3
      });
    }
  }

  // Economic instability
  if (worldState.economy?.instability > 0.5) {
    factors.push({
      type: 'economic_instability',
      description: 'Economic instability may cause economic cascades',
      multiplier: 1.2
    });
  }

  // Active conflicts
  if (worldState.activeConflicts && worldState.activeConflicts.length > 0) {
    factors.push({
      type: 'active_conflicts',
      description: 'Active conflicts may spread or intensify',
      multiplier: 1.4
    });
  }

  // Magical phenomena
  if (worldState.activeMagic && worldState.activeMagic.length > 0) {
    factors.push({
      type: 'magical_resonance',
      description: 'Active magical phenomena may interact unpredictably',
      multiplier: 1.25
    });
  }

  return factors;
}

return [{
  json: {
    ...cascadeConfig,
    worldContext: {
      worldState,
      cascadeHistory: cascadeHistory || [],
      relationships: relationships || {}
    },
    eventAnalysis,
    propagationMap: {
      vectors: eventAnalysis.propagation_vectors,
      domains: eventAnalysis.affected_domains,
      potential: eventAnalysis.cascade_potential,
      delay: eventAnalysis.propagation_delay,
      resonance: eventAnalysis.resonance_factors
    }
  }
}];

// Generate cascade effects for current depth
const cascadeData = $input.first().json;
const { currentDepth, initialEvent, worldContext, propagationMap, cascadeId } = cascadeData;

const cascadeEffects = [];
const currentTimestamp = new Date();

// Calculate delay based on propagation speed and depth
const delayMs = cascadeData.propagationMap.delay * 60 * 60 * 1000 * Math.pow(1.2, currentDepth);
const effectTimestamp = new Date(currentTimestamp.getTime() + delayMs);

// Generate effects for each propagation vector
propagationMap.vectors.forEach(vector => {
  const effects = generateVectorEffects(vector, initialEvent, worldContext, currentDepth);
  cascadeEffects.push(...effects);
});

function generateVectorEffects(vector, initialEvent, worldContext, depth) {
  const effects = [];
  const baseStrength = vector.strength * Math.pow(0.8, depth); // Decay over depth

  switch (vector.type) {
    case 'location':
      effects.push(...generateLocationEffects(vector, initialEvent, worldContext, baseStrength));
      break;
    case 'npc':
      effects.push(...generateNPCEffects(vector, initialEvent, worldContext, baseStrength));
      break;
    case 'faction':
      effects.push(...generateFactionEffects(vector, initialEvent, worldContext, baseStrength));
      break;
    case 'economic':
      effects.push(...generateEconomicEffects(vector, initialEvent, worldContext, baseStrength));
      break;
    case 'environmental':
      effects.push(...generateEnvironmentalEffects(vector, initialEvent, worldContext, baseStrength));
      break;
  }

  return effects;
}

function generateLocationEffects(vector, event, worldContext, strength) {
  const effects = [];
  const location = worldContext.worldState.locations?.find(loc => loc.id === vector.target);

  if (!location) return effects;

  // Direct location impact
  effects.push({
    id: `location_effect_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
    type: 'location_impact',
    target_type: 'location',
    target_id: location.id,
    target_name: location.name,
    effect_type: determineLocationEffectType(event.type),
    severity: calculateSeverity(strength, event.magnitude),
    description: generateLocationEffectDescription(location, event),
    immediate_consequences: generateLocationConsequences(location, event),
    timestamp: new Date().toISOString(),
    parent_event: event.id,
    cascade_depth: currentDepth,
    propagation_strength: strength
  });

  // Connected location impacts
  if (vector.connected_locations && vector.connected_locations.length > 0) {
    vector.connected_locations.slice(0, 3).forEach(connectedId => {
      const connectedLocation = worldContext.worldState.locations?.find(loc => loc.id === connectedId);
      if (connectedLocation && Math.random() < strength * 0.7) {
        effects.push({
          id: `connected_location_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
          type: 'location_impact',
          target_type: 'location',
          target_id: connectedLocation.id,
          target_name: connectedLocation.name,
          effect_type: 'ripple_effect',
          severity: calculateSeverity(strength * 0.6, event.magnitude),
          description: `Ripple effects from ${location.name} reach ${connectedLocation.name}`,
          timestamp: new Date().toISOString(),
          parent_event: event.id,
          cascade_depth: currentDepth,
          propagation_strength: strength * 0.6,
          source_location: location.id
        });
      }
    });
  }

  return effects;
}

function generateNPCEffects(vector, event, worldContext, strength) {
  const effects = [];
  const npc = worldContext.worldState.npcs?.find(n => n.id === vector.target);

  if (!npc) return effects;

  // Direct NPC impact
  effects.push({
    id: `npc_effect_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
    type: 'npc_impact',
    target_type: 'npc',
    target_id: npc.id,
    target_name: npc.name,
    effect_type: determineNPCEffectType(event.type, npc),
    severity: calculateSeverity(strength, event.magnitude),
    description: generateNPCEffectDescription(npc, event),
    behavioral_changes: generateNPCBehaviorChanges(npc, event, strength),
    relationship_changes: generateNPCRelationshipChanges(npc, vector.relationships, strength),
    timestamp: new Date().toISOString(),
    parent_event: event.id,
    cascade_depth: currentDepth,
    propagation_strength: strength
  });

  // Relationship propagation
  if (vector.relationships && vector.relationships.length > 0) {
    vector.relationships.slice(0, 2).forEach(relatedNpcId => {
      const relatedNpc = worldContext.worldState.npcs?.find(n => n.id === relatedNpcId);
      if (relatedNpc && Math.random() < strength * 0.8) {
        effects.push({
          id: `npc_relationship_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
          type: 'npc_impact',
          target_type: 'npc',
          target_id: relatedNpc.id,
          target_name: relatedNpc.name,
          effect_type: 'relationship_ripple',
          severity: calculateSeverity(strength * 0.5, event.magnitude),
          description: `${relatedNpc.name} is affected by events involving ${npc.name}`,
          behavioral_changes: generateNPCBehaviorChanges(relatedNpc, event, strength * 0.5),
          timestamp: new Date().toISOString(),
          parent_event: event.id,
          cascade_depth: currentDepth,
          propagation_strength: strength * 0.5,
          source_npc: npc.id
        });
      }
    });
  }

  return effects;
}

function generateFactionEffects(vector, event, worldContext, strength) {
  const effects = [];
  const faction = worldContext.worldState.factions?.find(f => f.id === vector.target);

  if (!faction) return effects;

  // Direct faction impact
  effects.push({
    id: `faction_effect_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
    type: 'faction_impact',
    target_type: 'faction',
    target_id: faction.id,
    target_name: faction.name,
    effect_type: determineFactionEffectType(event.type, faction),
    severity: calculateSeverity(strength, event.magnitude),
    description: generateFactionEffectDescription(faction, event),
    political_changes: generateFactionPoliticalChanges(faction, event, strength),
    resource_changes: generateFactionResourceChanges(faction, event, strength),
    timestamp: new Date().toISOString(),
    parent_event: event.id,
    cascade_depth: currentDepth,
    propagation_strength: strength
  });

  // Faction relationship propagation
  if (vector.relationships && vector.relationships.length > 0) {
    vector.relationships.slice(0, 2).forEach(relatedFactionId => {
      const relatedFaction = worldContext.worldState.factions?.find(f => f.id === relatedFactionId);
      if (relatedFaction && Math.random() < strength * 0.9) {
        effects.push({
          id: `faction_relationship_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
          type: 'faction_impact',
          target_type: 'faction',
          target_id: relatedFaction.id,
          target_name: relatedFaction.name,
          effect_type: 'diplomatic_ripple',
          severity: calculateSeverity(strength * 0.6, event.magnitude),
          description: `${relatedFaction.name} responds to events involving ${faction.name}`,
          diplomatic_changes: generateDiplomaticChanges(relatedFaction, faction, event, strength * 0.6),
          timestamp: new Date().toISOString(),
          parent_event: event.id,
          cascade_depth: currentDepth,
          propagation_strength: strength * 0.6,
          source_faction: faction.id
        });
      }
    });
  }

  return effects;
}

function generateEconomicEffects(vector, event, worldContext, strength) {
  const effects = [];

  // Market impact
  effects.push({
    id: `economic_effect_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
    type: 'economic_impact',
    target_type: 'economy',
    target_id: 'global_market',
    effect_type: determineEconomicEffectType(event.type),
    severity: calculateSeverity(strength, event.magnitude),
    description: generateEconomicEffectDescription(event),
    market_changes: {
      price_volatility: strength * 0.4,
      supply_disruption: strength * 0.3,
      demand_shift: strength * 0.3
    },
    affected_regions: vector.market_regions || ['local'],
    timestamp: new Date().toISOString(),
    parent_event: event.id,
    cascade_depth: currentDepth,
    propagation_strength: strength
  });

  return effects;
}

function generateEnvironmentalEffects(vector, event, worldContext, strength) {
  const effects = [];

  // Environmental spread
  effects.push({
    id: `environmental_effect_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
    type: 'environmental_impact',
    target_type: 'environment',
    effect_type: determineEnvironmentalEffectType(event.type),
    severity: calculateSeverity(strength, event.magnitude),
    description: generateEnvironmentalEffectDescription(event),
    affected_areas: vector.affected_biomes || ['all'],
    spread_pattern: vector.spread_pattern || 'radial',
    duration: calculateEnvironmentalDuration(event.type, strength),
    timestamp: new Date().toISOString(),
    parent_event: event.id,
    cascade_depth: currentDepth,
    propagation_strength: strength
  });

  return effects;
}

// Helper functions for effect generation
function determineLocationEffectType(eventType) {
  const types = {
    'combat': 'damage',
    'social': 'atmosphere_change',
    'economic': 'commerce_disruption',
    'environmental': 'environmental_change',
    'magical': 'magical_residue',
    'political': 'control_change'
  };
  return types[eventType] || 'general_impact';
}

function determineNPCEffectType(eventType, npc) {
  const types = {
    'combat': npc.combat_role ? 'combat_stress' : 'fear_response',
    'social': 'social_adjustment',
    'economic': 'financial_impact',
    'environmental': 'survival_response',
    'magical': 'magical_exposure',
    'political': 'political_alignment'
  };
  return types[eventType] || 'general_reaction';
}

function determineFactionEffectType(eventType, faction) {
  const types = {
    'combat': 'military_response',
    'social': 'public_opinion_shift',
    'economic': 'resource_allocation',
    'environmental': 'territory_impact',
    'magical': 'magical_policy',
    'political': 'political_strategy'
  };
  return types[eventType] || 'strategic_response';
}

function determineEconomicEffectType(eventType) {
  const types = {
    'combat': 'military_economy',
    'social': 'consumer_confidence',
    'economic': 'market_cycle',
    'environmental': 'resource_availability',
    'magical': 'magical_economy',
    'political': 'regulation_impact'
  };
  return types[eventType] || 'general_economic';
}

function determineEnvironmentalEffectType(eventType) {
  const types = {
    'combat': 'battlefield_scarring',
    'social': 'settlement_impact',
    'economic': 'resource_extraction',
    'environmental': 'ecosystem_change',
    'magical': 'magical_pollution',
    'political': 'land_use_change'
  };
  return types[eventType] || 'environmental_change';
}

function calculateSeverity(strength, magnitude) {
  const magnitudeMultipliers = {
    'minor': 0.5,
    'normal': 1.0,
    'major': 1.5,
    'catastrophic': 2.0
  };

  const adjustedStrength = strength * (magnitudeMultipliers[magnitude] || 1.0);

  if (adjustedStrength < 0.3) return 'trivial';
  if (adjustedStrength < 0.6) return 'minor';
  if (adjustedStrength < 1.2) return 'moderate';
  if (adjustedStrength < 1.8) return 'major';
  return 'catastrophic';
}

function generateLocationEffectDescription(location, event) {
  const templates = {
    'combat': `The events at ${location.name} have left visible marks and altered the local atmosphere.`,
    'social': `Social dynamics in ${location.name} have shifted due to recent events.`,
    'economic': `Economic activity in ${location.name} has been disrupted by recent developments.`,
    'environmental': `The environment around ${location.name} shows signs of change.`,
    'magical': `Magical energies around ${location.name} have been altered by recent events.`,
    'political': `Political control over ${location.name} is in flux.`
  };
  return templates[event.type] || `Recent events have affected ${location.name}.`;
}

function generateNPCEffectDescription(npc, event) {
  return `${npc.name} has been affected by recent events, showing changes in behavior and outlook.`;
}

function generateFactionEffectDescription(faction, event) {
  return `The ${faction.name} faction is responding to recent events with strategic adjustments.`;
}

function generateEconomicEffectDescription(event) {
  return 'Economic conditions are shifting in response to recent events.';
}

function generateEnvironmentalEffectDescription(event) {
  return 'Environmental patterns are showing signs of change.';
}

function generateLocationConsequences(location, event) {
  return [
    'altered atmosphere',
    'changed perception',
    'new opportunities',
    'increased danger'
  ];
}

function generateNPCBehaviorChanges(npc, event, strength) {
  return {
    mood_adjustment: (Math.random() - 0.5) * strength,
    activity_level_change: (Math.random() - 0.5) * strength,
    caution_level: Math.random() * strength,
    new_goals: Math.random() < strength ? 1 : 0
  };
}

function generateNPCRelationshipChanges(npc, relationships, strength) {
  const changes = {};
  relationships.slice(0, 2).forEach(relatedId => {
    changes[relatedId] = (Math.random() - 0.5) * strength * 20; // -10 to +10
  });
  return changes;
}

function generateFactionPoliticalChanges(faction, event, strength) {
  return {
    leadership_stability: Math.max(0, 1 - strength * 0.3),
    public_support: (Math.random() - 0.5) * strength * 0.4,
    policy_changes: Math.random() < strength ? 1 : 0
  };
}

function generateFactionResourceChanges(faction, event, strength) {
  return {
    military_strength: (Math.random() - 0.5) * strength * 0.2,
    economic_resources: (Math.random() - 0.5) * strength * 0.3,
    influence: (Math.random() - 0.5) * strength * 0.25
  };
}

function generateDiplomaticChanges(targetFaction, sourceFaction, event, strength) {
  return {
    relationship_change: (Math.random() - 0.5) * strength * 15,
    trade_agreements: Math.random() < strength * 0.3 ? 'reviewed' : 'unchanged',
    diplomatic_stance: Math.random() < strength * 0.2 ? 'shifted' : 'stable'
  };
}

function calculateEnvironmentalDuration(eventType, strength) {
  const baseDurations = {
    'combat': '1-3 days',
    'environmental': '1-2 weeks',
    'magical': '3-7 days',
    'economic': '1-2 weeks'
  };

  const multiplier = strength > 1 ? 2 : 1;
  return baseDurations[eventType] || '1 week';
}

return [{
  json: {
    ...cascadeData,
    currentDepth: currentDepth + 1,
    cascadeEffects,
    effectsGenerated: cascadeEffects.length,
    lastPropagationTime: new Date().toISOString(),
    propagationHistory: [
      ...cascadeData.propagationHistory,
      {
        depth: currentDepth,
        effects_count: cascadeEffects.length,
        timestamp: new Date().toISOString()
      }
    ]
  }
}];

