// Process narratives and prepare for next cascade iteration
const cascadeData = $input.first().json;
const deepseekResponse = $input.last().json;

let narrativeData = {};
try {
  const content = deepseekResponse.choices[0].message.content;
  narrativeData = JSON.parse(content);
} catch (error) {
  console.error('Failed to parse DeepSeek cascade narrative:', error);
  narrativeData = {
    narrative_description: 'The effects of the event continue to ripple through the world.',
    player_perception: 'Changes in the world become gradually apparent.',
    player_hooks: 'Opportunities for investigation or intervention may arise.',
    foreshadowing: 'Further consequences may develop over time.'
  };
}

// Enrich cascade effects with narratives
const enrichedEffects = cascadeData.cascadeEffects.map((effect, index) => {
  const effectNarrative = narrativeData.effects?.[index] || narrativeData;

  return {
    ...effect,
    narrative_description: effectNarrative.narrative_description || `The world responds with ${effect.effect_type}`,
    player_perception: effectNarrative.player_perception || 'This change may be noticed through careful observation.',
    player_hooks: effectNarrative.player_hooks || 'This may present new opportunities or challenges.',
    foreshadowing: effectNarrative.foreshadowing || 'Further effects may follow.',
    processed: true
  };
});

// Check if cascade should continue
const shouldContinue = cascadeData.currentDepth < cascadeData.cascadeDepth && 
                      enrichedEffects.length > 0 && 
                      cascadeData.systemState.active;

// Prepare next iteration data
const nextIterationData = shouldContinue ? {
  ...cascadeData,
  cascadeEffects: enrichedEffects,
  narrative_summary: narrativeData.narrative_description || 'Cascade effects continue to propagate',
  effects_enriched: enrichedEffects.length
} : cascadeData;

return [{
  json: {
    ...nextIterationData,
    cascadeEffects: enrichedEffects,
    narrativeData,
    shouldContinue,
    processing_complete: !shouldContinue
  }
}];

// Generate cascade branch points for parallel processing
const cascadeData = $input.first().json;
const { cascadeEffects, shouldContinue, currentDepth } = cascadeData;

if (!shouldContinue) {
  return [{ json: { ...cascadeData, branches: [] } }];
}

// Identify effects that can spawn new cascade branches
const potentialBranches = cascadeEffects.filter(effect => {
  // Effects with high severity can spawn branches
  if (['major', 'catastrophic'].includes(effect.severity)) return true;

  // Effects affecting multiple targets can spawn branches
  if (effect.target_type === 'faction' || effect.target_type === 'environmental') return true;

  // Effects with strong propagation strength
  if (effect.propagation_strength > 0.7) return true;

  return false;
});

// Generate branch data
const branches = potentialBranches.slice(0, 3).map((effect, index) => {
  return {
    branch_id: `${cascadeData.cascadeId}_branch_${index}`,
    parent_effect_id: effect.id,
    source_event: effect,
    remaining_depth: cascadeData.cascadeDepth - currentDepth,
    propagation_modifier: effect.propagation_strength,
    branch_type: determineBranchType(effect),
    priority: calculateBranchPriority(effect),
    delay: calculateBranchDelay(effect, currentDepth),
    conditions: generateBranchConditions(effect)
  };
});

function determineBranchType(effect) {
  const types = {
    'location_impact': 'territorial',
    'npc_impact': 'social',
    'faction_impact': 'political',
    'economic_impact': 'economic',
    'environmental_impact': 'environmental'
  };
  return types[effect.type] || 'general';
}

function calculateBranchPriority(effect) {
  let priority = 5;

  // Severity factor
  if (effect.severity === 'catastrophic') priority += 3;
  else if (effect.severity === 'major') priority += 2;
  else if (effect.severity === 'moderate') priority += 1;

  // Propagation strength factor
  priority += effect.propagation_strength * 2;

  // Target importance factor
  if (effect.target_type === 'faction') priority += 2;
  if (effect.target_type === 'environmental') priority += 1;

  return Math.min(priority, 10);
}

function calculateBranchDelay(effect, depth) {
  const baseDelay = (depth + 1) * 2; // hours
  const severityMultiplier = {
    'catastrophic': 0.5,
    'major': 0.75,
    'moderate': 1.0,
    'minor': 1.5,
    'trivial': 2.0
  };

  return baseDelay * (severityMultiplier[effect.severity] || 1.0);
}

function generateBranchConditions(effect) {
  return {
    minimum_propagation_strength: 0.3,
    required_context: [effect.target_type],
    exclusion_factors: ['player_intervention'],
    environmental_factors: effect.target_type === 'environmental' ? ['weather', 'magic'] : []
  };
}

return [{
  json: {
    ...cascadeData,
    branches,
    total_branches: branches.length,
    cascade_complete: !shouldContinue
  }
}];

// Generate final cascade summary
const cascadeData = $input.first().json;

const summary = {
  cascade_id: cascadeData.cascadeId,
  campaign_id: cascadeData.campaignId,
  completion_time: new Date().toISOString(),
  cascade_statistics: {
    total_depths_processed: cascadeData.currentDepth,
    max_depth: cascadeData.cascadeDepth,
    total_effects_generated: cascadeData.cascadeEffects?.length || 0,
    branches_created: cascadeData.total_branches || 0,
    propagation_vectors_used: cascadeData.propagationMap?.vectors?.length || 0,
    affected_domains: cascadeData.propagationMap?.domains || [],
    cascade_potential: cascadeData.propagationMap?.potential || 0
  },
  impact_summary: {
    locations_affected: cascadeData.cascadeEffects?.filter(e => e.target_type === 'location').length || 0,
    npcs_affected: cascadeData.cascadeEffects?.filter(e => e.target_type === 'npc').length || 0,
    factions_affected: cascadeData.cascadeEffects?.filter(e => e.target_type === 'faction').length || 0,
    economic_impacts: cascadeData.cascadeEffects?.filter(e => e.target_type === 'economy').length || 0,
    environmental_impacts: cascadeData.cascadeEffects?.filter(e => e.target_type === 'environment').length || 0
  },
  severity_distribution: calculateSeverityDistribution(cascadeData.cascadeEffects || []),
  narrative_summary: cascadeData.narrative_summary || 'Event cascade processing completed',
  player_hooks: extractPlayerHooks(cascadeData.cascadeEffects || []),
  next_steps: generateNextSteps(cascadeData),
  cascade_complete: cascadeData.cascade_complete || true
};

function calculateSeverityDistribution(effects) {
  const distribution = {
    trivial: 0,
    minor: 0,
    moderate: 0,
    major: 0,
    catastrophic: 0
  };

  effects.forEach(effect => {
    if (distribution.hasOwnProperty(effect.severity)) {
      distribution[effect.severity]++;
    }
  });

  return distribution;
}

function extractPlayerHooks(effects) {
  return effects
    .filter(effect => effect.player_hooks && effect.player_hooks.length > 0)
    .map(effect => ({
      effect_id: effect.id,
      hook_type: effect.effect_type,
      hooks: effect.player_hooks,
      target: effect.target_name,
      severity: effect.severity
    }));
}

function generateNextSteps(cascadeData) {
  const steps = [];

  // Continue monitoring if there are branches
  if (cascadeData.total_branches > 0) {
    steps.push({
      action: 'monitor_branches',
      description: 'Monitor cascade branches for further propagation',
      priority: 'high',
      timeline: 'next 1-24 hours'
    });
  }

  // Player involvement recommendations
  if (cascadeData.playerInvolvement) {
    steps.push({
      action: 'player_notification',
      description: 'Notify players of significant world changes',
      priority: 'medium',
      timeline: 'immediate'
    });
  }

  // World state update
  steps.push({
    action: 'world_state_update',
    description: 'Update campaign world state with cascade effects',
    priority: 'high',
    timeline: 'immediate'
  });

  return steps;
}

return [{ json: summary }];
